//! Original requirement-bool union over actual full selected CODE originals.
//! The host alone seals both source traversals and the same native body owner.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_raw_file::Config,reactive_raw_policy_pages::RawPolicyPages,captured_allow_annotations::Operation,key_policy_control::{self as kc,Control},requirement_bool_policy as policy,lint::Site};
use std::{collections::{BTreeMap,HashSet},io,path::Path,sync::Arc};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn check(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}check(b,poll)?;pending}
pub struct RequirementData{sites:Vec<Site>,source_text:Vec<String>}
impl RequirementData{pub fn metadata(&self)->&'static crate::lint::Meta{policy::metadata()}pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[crate::lint::AllowUse]{&[]}pub fn allow_source_digest(&self,_:&str)->Option<&[u8;20]>{None}pub fn notes(&self)->&[String]{&[]}pub fn serialize_data<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{serde::Serialize::serialize(&(&self.sites,&self.source_text),s)}pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.source_text.capacity().checked_mul(std::mem::size_of::<String>())?)?;for site in &self.sites{for text in[&site.rule,&site.rel,&site.msg,&site.key,&site.ident]{n=n.checked_add(text.capacity())?}}for text in &self.source_text{n=n.checked_add(text.capacity())?}Some(n)}}
pub fn metadata()->&'static crate::lint::Meta{policy::metadata()}
pub fn selects_path(relative:&str)->bool{relative.starts_with("code/")&&relative.ends_with(".dm")&&!relative.split('/').any(|part|part.starts_with('.'))}
struct Work<'a>{budget:&'a Budget,poll:&'a dyn Fn()->io::Result<()>,temporary:usize}
impl dm_analysis::policy_body_demand::WorkspaceWork for Work<'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{check(self.budget,self.poll)}fn retain(&mut self,bytes:usize)->Result<(),Failure>{self.budget.charge(bytes).map_err(|m|oom(self.budget,m))}fn temporary(&mut self,bytes:usize)->Result<(),Failure>{if bytes>self.temporary{self.budget.charge(bytes-self.temporary).map_err(|m|oom(self.budget,m))?;self.temporary=bytes;}Ok(())}fn overflow(&mut self)->Failure{oom(self.budget,"requirement body/source work geometry overflow")}fn allocation_failed(&mut self)->Failure{oom(self.budget,"requirement body/source work allocation refused")}fn body<'a>(&mut self,archive:&'a dm_tree::frontend::BodyArchive,ordinal:usize)->Result<dm_tree::frontend::ArchivedBody<'a>,Failure>{check(self.budget,self.poll)?;archive.parse_checked(ordinal).map_err(|error|match error{dm_tree::frontend::BodySyntaxFailure::Operational(actual)=>Failure::Operational(actual),dm_tree::frontend::BodySyntaxFailure::Syntax(error)=>Failure::Unsupported(error.message)})}}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
fn push(data:&mut RequirementData,rule:&'static str,relative:&str,line:usize,text:&str,budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{let mut work=Operation{budget,poll};work.checkpoint()?;kc::row(&mut work,&mut data.sites)?;data.sites.push(Site{rule:kc::own(&mut work,rule)?,rel:kc::own(&mut work,relative)?,line:u32::try_from(line).map_err(|_|oom(budget,"requirement line overflow"))?,msg:String::new(),key:String::new(),ident:String::new()});kc::row(&mut work,&mut data.source_text)?;kc::reserve(&mut work,||text.len().checked_mul(4)?.checked_add(128))?;data.source_text.push(crate::util::normalize_ws(text));Ok(())}
pub fn collect_from_pages(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<RequirementData,Failure>{
 check(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&phase.budget;let pending=(||{let empty=crate::scopes::LintScope::default();let scope=config.borrowed_report_scope("requirement_bool","").unwrap_or(&empty);let mut work=Operation{budget,poll};let scanner=policy::Scanner::new();let mut selected=HashSet::new();let mut calls=policy::Calls::new();
 let facts=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{check(local,poll)?;if !selects_path(relative){return Err("requirement source escaped actual nonhidden CODE selection".into())}let file=views.source_file()?;let mut temp=Operation{budget:local,poll};kc::reserve(&mut work,||relative.len().checked_mul(4)?.checked_add(2048))?;selected.insert(kc::own(&mut work,relative)?);for(line,code)in file.code().numbered(){temp.checkpoint()?;if scanner.matches(code){calls.insert(relative,line,&mut work)?;}}Ok(true)})();finish(pending,local,poll)})?;if !facts{return Err("requirement source union omitted actual selected CODE EOF".into())}
 let mut body_work=Work{budget,poll,temporary:0};let typed=dm_analysis::analyze_call_sites::named_workspace_using(inputs,root_path,&["req_bool"],&mut body_work)?;for(relative,line,_)in typed{calls.typed(&relative,line as usize,&selected,&mut work)?;}
 let mut texts:BTreeMap<(String,usize),String>=BTreeMap::new();let mut retired=RequirementData{sites:Vec::new(),source_text:Vec::new()};let complete=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{check(local,poll)?;let file=views.source_file()?;let mut temp=Operation{budget:local,poll};for(path,line)in calls.rows(){temp.checkpoint()?;if path!=relative{continue}let raw=file.raw();let text=if *line>0&&*line<=raw.num_lines(){raw.line(*line)}else{""};kc::reserve(&mut work,||Some(2048))?;texts.insert((kc::own(&mut work,path)?,*line),kc::own(&mut work,text)?);}for(line,code)in file.code().numbered(){temp.checkpoint()?;let mut hit=false;for name in scope.list("retired_macros"){temp.checkpoint()?;if policy::retired_name_using(code,name,&mut temp)?{hit=true;break}}if hit{let raw=file.raw();let text=if line>0&&line<=raw.num_lines(){raw.line(line)}else{""};push(&mut retired,"legacy_macro",relative,line,text,budget,poll)?;}}Ok(true)})();finish(pending,local,poll)})?;if !complete{return Err("requirement judgment omitted actual selected CODE EOF".into())}
 if texts.len()!=calls.rows().len(){return Err("requirement selected source text was not actually visited".into())}let mut data=RequirementData{sites:Vec::new(),source_text:Vec::new()};for((relative,line),text)in texts{work.checkpoint()?;push(&mut data,"boolean_callback",&relative,line,&text,budget,poll)?;}for(site,text)in retired.sites.into_iter().zip(retired.source_text){work.checkpoint()?;kc::row(&mut work,&mut data.sites)?;kc::row(&mut work,&mut data.source_text)?;data.sites.push(site);data.source_text.push(text);}check(budget,poll)?;Ok(data)})();let pending=finish(pending,budget,poll);let pending=match pending{Ok(data)=>{let charge=data.retained_charge().ok_or_else(||oom(root,"requirement output geometry overflow"))?;match root.charge(charge).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)
}
